mapper.select:

and status = #{status}
and d.tenant_id is null	and d.tenant_tower_dept_id is null
and d.tenant_id = #{tenantId}
and (dept_id = #{deptId} OR INSTR(ANCESTORS, #{deptId})>0)
order by d.parent_id ASC, d.dept_id ASC, d.order_num ASC

select  s.tenant_name, d.TENANT_ID as tenantId,   d.TENANT_TOWER_DEPT_ID as tenantTowerDeptId,  d.id, d.dept_id, d.parent_id,d.parent_name, d.ancestors, d.dept_name, d.order_num, d.leader, d.phone, d.email, d.status, d.del_flag, d.create_by, d.create_time, d.dept_level,d.bussness_unit,d.MDM_ORG_CODE as mdmOrgCode,d.industry_code as industryCode,
CASE WHEN d.parent_id = '1' THEN NULL WHEN d.parent_id = '100000' THEN d.dept_id ELSE d.parent_id END province,
CASE WHEN d.parent_id = '1' THEN NULL WHEN d.parent_id = '100000' THEN NULL ELSE d.dept_id END city,d.app_ver_code
from sys_dept d
left join sys_tenant_info s on d.tenant_id = s.tenant_id
where d.del_flag = '0' AND d.status = '0'
AND d.TENANT_ID is not null AND s.del_flag = '0'

	AND d.parent_id = #{parentId}


	AND d.dept_name like CONCAT(CONCAT('%',#{deptName}),'%')


	AND d.tenant_id = #{tenantId}


	AND d.industry_code = #{industryCode}


	AND d.tenant_tower_dept_id = #{tenantTowerDeptId}


	AND s.tenant_name like CONCAT(CONCAT('%',#{tenantName}),'%')



	${dataScope}

order by d.parent_id ASC, d.dept_id ASC, d.order_num ASC

SELECT d.tenant_id AS tenantId, d.id, d.dept_id, d.dept_name, d.parent_id, d.parent_name, d.MDM_ORG_CODE as mdmOrgCode, d.industry_code as industryCode, u.user_id AS userId, u.user_name AS leader, u.nick_name AS nickName, u.phonenumber AS phone, u.sex AS sex FROM sys_dept d LEFT JOIN ( WITH RECURSIVE cte AS ( SELECT 1 AS n UNION ALL SELECT n + 1 FROM cte WHERE n < 50 ) SELECT u_inner.user_id, u_inner.user_name, u_inner.nick_name, u_inner.phonenumber, u_inner.sex, SUBSTRING_INDEX(SUBSTRING_INDEX(u_inner.DEPT_ID, ',', n), ',', -1) AS split_dept_id FROM sys_user u_inner JOIN cte ON cte.n <= ( LENGTH(u_inner.DEPT_ID) - LENGTH(REPLACE(u_inner.DEPT_ID, ',', '')) + 1 ) WHERE u_inner.DEL_FLAG = '0' ) u_split ON d.dept_id = u_split.split_dept_id LEFT JOIN sys_user u ON u_split.user_id = u.user_id WHERE d.del_flag = '0' AND d.tenant_id = #{tenantId} AND d.dept_id like concat(#{deptId}, '%')
and d.INDUSTRY_CODE = #{industryCode}
and d.APP_VER_CODE = #{appVerCode}
AND u.user_id in (select ur.user_id from sys_user_role ur where ur.role_id = #{roleId})
ORDER BY d.parent_id ASC, d.dept_id ASC, d.order_num ASC

select  s.tenant_name, d.TENANT_ID as tenantId,   d.TENANT_TOWER_DEPT_ID as tenantTowerDeptId,  d.id, d.dept_id, d.parent_id,d.parent_name, d.ancestors, d.dept_name, d.order_num, d.leader, d.phone, d.email, d.status, d.del_flag, d.create_by, d.create_time, d.dept_level,d.bussness_unit,
CASE WHEN d.parent_id = '1' THEN NULL WHEN d.parent_id = '100000' THEN d.dept_id ELSE d.parent_id END province,
CASE WHEN d.parent_id = '1' THEN NULL WHEN d.parent_id = '100000' THEN NULL ELSE d.dept_id END city,d.app_ver_code,
d.MDM_ORG_CODE as mdmOrgCode,d.industry_code as industryCode
from sys_dept d
left join sys_tenant_info s on d.tenant_id = s.tenant_id
where d.del_flag = '0'
AND d.TENANT_ID is not null

	AND d.parent_id = #{parentId}


	AND d.dept_name like CONCAT(CONCAT('%',#{deptName}),'%')


	AND d.status = #{status}


	AND d.tenant_id = #{tenantId}


	AND d.tenant_tower_dept_id = #{tenantTowerDeptId}


	AND s.tenant_name like CONCAT(CONCAT('%',#{tenantName}),'%')


	AND d.industry_code = #{industryCode}


	AND d.app_ver_code = #{appVerCode}



	${dataScope}

order by d.parent_id ASC, d.dept_id ASC, d.order_num ASC

SELECT DISTINCT d.id, d.tenant_id AS tenantId, d.dept_id, d.dept_name, d.parent_id, d.parent_name, d.MDM_ORG_CODE as mdmOrgCode, d.industry_code as industryCode, u.user_id AS userId, u.user_name AS leader, u.nick_name AS nickName, u.phonenumber AS phone, u.sex AS sex, u.avatar AS avatar FROM sys_dept d LEFT JOIN ( WITH RECURSIVE cte AS ( SELECT 1 AS n UNION ALL SELECT n + 1 FROM cte WHERE n < 50 ) SELECT u_inner.user_id, SUBSTRING_INDEX(SUBSTRING_INDEX(u_inner.DEPT_ID, ',', n), ',', -1) AS split_dept_id FROM sys_user u_inner JOIN cte ON cte.n <= ( LENGTH(u_inner.DEPT_ID) - LENGTH(REPLACE(u_inner.DEPT_ID, ',', '')) + 1 ) WHERE u_inner.DEL_FLAG = '0' ) u_split ON d.dept_id = u_split.split_dept_id LEFT JOIN sys_user u ON u_split.user_id = u.user_id
and u.status = #{status}
WHERE d.del_flag = '0' AND d.tenant_id = #{tenantId} and d.INDUSTRY_CODE=#{industryCode}

SELECT d.dept_id as id,a.area_name as areaName,d.tenant_id AS tenantId,a.area_parent_code as pid,d.DEPT_LEVEL as deptLevel,a.area_level as areaLevel from sys_dept d inner join sys_area a on d.dept_id = a.area_code
 WHERE d.del_flag = '0'  and  d.industry_code='999999'

	and d.DEPT_LEVEL < 4


	and d.PARENT_ID=#{deptId}


	and  d.DEPT_ID=#{deptId}

order by d.DEPT_ID DESC

SELECT DISTINCT a1.AREA_CODE AS id,a1.area_name AS areaName,a1.AREA_PARENT_CODE AS pid FROM sys_area a1 WHERE a1.area_level<=4 AND a1.area_parent_code IN
#{item}
UNION ALL SELECT DISTINCT a1.AREA_CODE AS id,a1.area_name AS areaName,a1.AREA_PARENT_CODE AS pid FROM sys_area a1 WHERE a1.area_level<=4 AND a1.area_code IN
#{item}
UNION ALL SELECT a2.AREA_CODE AS id,a2.area_name AS areaName,a2.AREA_PARENT_CODE AS pid FROM sys_area a1 LEFT JOIN sys_area a2 ON a1.AREA_PARENT_CODE = a2.AREA_CODE WHERE a1.area_level<=4 AND a1.area_code IN
#{item}

SELECT DISTINCT sa.AREA_CODE AS id,sa.area_name AS areaName,sa.AREA_PARENT_CODE AS pid FROM sys_area_manage_rel samr, sys_area sa WHERE samr.area_code = sa.AREA_CODE AND sa.DEL_FLAG = '0' AND samr.dept_code = #{deptId}
UNION ALL SELECT DISTINCT sa.AREA_CODE AS id,sa.area_name AS areaName,sa.AREA_PARENT_CODE AS pid FROM sys_area_manage_rel samr, sys_area sa WHERE samr.area_code = sa.AREA_PARENT_CODE and samr.dept_code = #{deptId} AND sa.DEL_FLAG = '0' and sa.AREA_LEVEL = '3' UNION ALL SELECT DISTINCT sa.AREA_CODE AS id,sa.area_name AS areaName,sa.AREA_PARENT_CODE AS pid FROM ( SELECT DISTINCT sa.AREA_CODE AS id,sa.area_name AS areaName,sa.AREA_PARENT_CODE AS pid FROM sys_area_manage_rel samr, sys_area sa WHERE samr.area_code = sa.AREA_PARENT_CODE and samr.dept_code = #{deptId} AND sa.DEL_FLAG = '0' and sa.AREA_LEVEL = '3' ) samr, sys_area sa where sa.AREA_PARENT_CODE = samr.id AND sa.DEL_FLAG = '0' AND sa.AREA_LEVEL = '4'
UNION ALL SELECT DISTINCT sa.AREA_CODE AS id,sa.area_name AS areaName,sa.AREA_PARENT_CODE AS pid FROM sys_area_manage_rel samr, sys_area sa WHERE sa.AREA_PARENT_CODE = samr.area_code and samr.dept_code = #{deptId} AND sa.DEL_FLAG = '0' AND sa.AREA_LEVEL = '4'

